// ---------- the wall ----------
// Every torch leaves a name painted on it and the wall only ever grows. It is the one
// thing here that survives a reset, so it lives in its own localStorage key — passing the
// torch wipes S, and a corrupted game save must not take the wall down with it.
const CHAVE_MURO = "jogo_brasil_muro";
const MURO_MAX = 30;               // it grows, but not without bound
let MURO: MuroEntrada[] = [];
function carregarMuro() {
  let bruto: string | null = null;
  try { bruto = localStorage.getItem(CHAVE_MURO); } catch (e) {}
  if (bruto) { try { const v = JSON.parse(bruto); if (Array.isArray(v)) MURO = v; } catch (e) {} }
  // hand-edited or half-written records get repaired, never thrown
  MURO = (Array.isArray(MURO) ? MURO : []).filter(function (e) {
    return e && typeof e === "object" && typeof e.nome === "string" && e.nome.length < 24;
  }).map(function (e, i) {
    return {
      n: (typeof e.n === "number" && isFinite(e.n) && e.n > 0) ? Math.floor(e.n) : i + 1,
      nome: e.nome,
      prox: typeof e.prox === "string" ? e.prox.slice(0, 23) : "",
      proj: (typeof e.proj === "number" && isFinite(e.proj) && e.proj >= 0) ? Math.floor(e.proj) : 0,
      cauda: typeof e.cauda === "string" ? e.cauda.slice(0, 40) : "",
      estilo: (typeof e.estilo === "number" && isFinite(e.estilo)) ? (Math.floor(e.estilo) % 6 + 6) % 6 : 0
    };
  }).slice(-MURO_MAX);
}
