  mataFarL: [[158, 172, 90], 0.36],
  mataFarK: [[66, 88, 44], 0.21],
  mataMid:  [[86, 112, 50], 0.20],
  mataMidL: [[126, 148, 66], 0.17],
  mataMidK: [[44, 60, 32], 0.10],
  mataNear:  [[58, 84, 40], 0.04],
  mataNearL: [[98, 124, 54], 0.03],
  mataNearK: [[28, 40, 24], 0.02],
  rodape:  [[34, 46, 24], 0],
