  trilha:  [[142, 118, 80], 0],
  trilhaL: [[176, 150, 104], 0],
  sulcoA:  [[100, 80, 52], 0],
  sulcoB:  [[198, 176, 128], 0],
  gramaA:  [[86, 104, 46], 0],
  gramaB:  [[66, 82, 36], 0],
  folha:   [[118, 143, 66], 0],
  agua:    [[84, 130, 125], 0],
  aguaFundo: [[44, 74, 72], 0],
  aguaRef: [[64, 104, 100], 0.10],
  brilho:  [[218, 216, 192], 0],
  junco:   [[66, 92, 42], 0],
  frenteC: [[34, 48, 24], 0],
  frenteL: [[64, 84, 36], 0],
  // THE PROSCENIUM'S OWN GREENS, wave 14. They used to be `frenteC/frenteL` — the same two
