  // green, it is a deeper and more saturated one.
  colunaC: [[16, 33, 11], 0],
  colunaL: [[36, 62, 17], 0],
  colunaB: [[62, 90, 31], 0.03],
  // the masonry half of the proscenium: TERRA/ACENTO, held at the same value as the foliage
