    cx.fillRect(x - rr, y - rr + ins, rr * 2, rr * 2 - ins * 2);  // an octagon out of two
    cx.fillRect(x - rr + ins, y - rr, rr * 2 - ins * 2, rr * 2);  // crossed rectangles
