    colunaC: [[15, 25, 10], 0],
    colunaL: [[29, 43, 16], 0],
    colunaB: [[50, 68, 26], 0.02],
    muroC: [[33, 25, 13], 0],
    muroM: [[43, 33, 17], 0],
    muroK: [[14, 10, 6], 0],
    muroL: [[63, 49, 25], 0],
    muroS: [[29, 23, 13], 0],
    // the forest floor: leaf litter over damp earth, warmer and darker than the street's stone
    // and the floor is the DARK END of the value architecture, which in this place is a real
    // number and not a habit: the panel's two bottom fifths mean RGB 54,49,20 and 48,49,28,
    // i.e. L 48 — the darkest thing in the picture, because everything standing between the
