    trilha:  [[72, 56, 32], 0],
    trilhaL: [[98, 80, 46], 0],
    sulcoA:  [[46, 34, 20], 0],
    sulcoB:  [[118, 100, 64], 0],
    gramaA:  [[62, 80, 34], 0],
    gramaB:  [[42, 58, 25], 0],
    folha:   [[88, 108, 46], 0],
    rodape:  [[18, 26, 13], 0],
    frenteC: [[18, 28, 13], 0],
